('lib/content/gpx_scolarite/dps_dpg/sanction_pages/causes_aggravation_sanction/moyen_cryptologie_page.dart','f00017','3 : CHAMP D''APPLICATION',17,'TextSpan','L''article ','L''article ','{}'::jsonb,true),
