('lib/content/gpx_scolarite/dps_dpg/sanction_pages/causes_aggravation_sanction/temoin_victime_partie_civile_page.dart','f00010','2.2 - Pour l''empêcher de dénoncer les faits, de porter plainte ou de déposer en justice',10,'_SubTitle','2.2 - Pour l''empêcher de dénoncer les faits, de porter plainte ou de déposer en justice','2.2 - Pour l''empêcher de dénoncer les faits, de porter plainte ou de déposer en justice','{}'::jsonb,true),
